"""X-MFG-36 in-house two-stage diaphragm H2 compressor for CRYO_H2 (A-M-169). Equal pressure ratio per stage, intercooled to 35 C; stage work
W = k/(k-1) R T1/M (r^((k-1)/k) - 1)/eta_ad (ideal gas, Perry's sec. 10 [DOE_H2_COMP] with k from NIST_WEBBOOK); swept volume per stroke from the
suction flow, speed and volumetric efficiency; diaphragm diameter from a shallow spherical-cap cavity, V about pi D^2 h / 8.
Average power on the energy balance; sized at the peak rate (run hours). Two compressors (one standby) per the redundancy rule.
Run: python3 -m flow_graph.param.h2_compressor [--write]"""
import json, math, os, sys
from . import drivers as DR
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
GP = os.path.join(ROOT, 'flow_graph/plant_flow_graph.json')
def design(d, g):
    v = lambda k: DR.val(d, k); m_d = sum(e['rate']['value'] for e in g['edges'] if e['to_unit_id'] == 'CRYO_H2' and 'mass' in e['layers'])
    r = (v('h2c_P2_bar')/v('h2c_P1_bar'))**0.5; k = v('h2c_k'); T1 = 308.15; Rm = 8.314/0.002016
    w = 2*k/(k - 1)*Rm*T1*(r**((k - 1)/k) - 1)/v('h2c_eta_ad')                 # J/kg, two stages
    m_pk = m_d/v('h2c_run_h')/3600; P_avg = m_d/86400*w/v('h2c_eta_motor')/1000; P_pk = m_pk*w/v('h2c_eta_motor')/1000
    st = []
    for i, Ps in enumerate((v('h2c_P1_bar'), v('h2c_P1_bar')*r)):
        rho = Ps*1e5/(Rm*T1); Vs = m_pk/rho/(v('h2c_rpm')/60*v('h2c_eta_v')); h = v('h2c_cavity_h_mm')/1000
        st.append(dict(stage=i + 1, P_in_bar=Ps, P_out_bar=Ps*r, T_out_C=T1*r**((k - 1)/k) - 273.15, swept_cm3=Vs*1e6, diaphragm_D_mm=math.sqrt(8*Vs/(math.pi*h))*1000))
    return dict(H2_kg_d=m_d, ratio_per_stage=r, kWh_per_kg=w/3.6e6/v('h2c_eta_motor'), P_avg_kW=P_avg, P_peak_kW=P_pk, stages=st, units=2,
                material='head and plates 17-4PH H1150 / 316L (hydrogen service), triple-layer 301 SS diaphragm with leak detection between layers')
def write(g, r):
    N = {n['unit_id']: n for n in g['nodes']}; E = {e['stream_id']: e for e in g['edges']}; n = N['CRYO_H2']
    n['params']['compressor_design'] = json.loads(json.dumps(r, default=float)); n['params']['compressor'] = 'in-house two-stage diaphragm, 10 to 200 bar, 2 x 100 % (X-MFG-36)'
    n['continuous_kw'] = {'value': round(r['P_avg_kW'], 4), 'unit': 'kW', 'status': 'study', 'note': f"X-MFG-36 (A-M-169): {r['H2_kg_d']:.2f} kg/d x {r['kWh_per_kg']:.2f} kWh/kg; peak {r['P_peak_kW']:.2f} kW over the run hours."}
    for sid in ('SF-CRYO_H2', 'SQ-CRYO_H2'):
        if sid in E: E[sid]['rate']['value'] = round(r['P_avg_kW'], 4)
    open(GP, 'w').write(json.dumps(g, indent=2))
    md = ['# Hydrogen compressor', '', 'Document number: AQS-DUTY-067', 'Revision: A', 'Date: 2026-10-15', 'Authority: AQS-PLAN-007 X-MFG-36. Generated by `flow_graph/param/h2_compressor.py`. Study. A-M-169.', '',
          f"{r['H2_kg_d']:.2f} kg/d H2, two stages at ratio {r['ratio_per_stage']:.2f}, intercooled to 35 C: {r['kWh_per_kg']:.2f} kWh/kg; average {r['P_avg_kW']:.3f} kW, peak {r['P_peak_kW']:.3f} kW. Two units, one standby.", '',
          '| Stage | In bar | Out bar | Discharge C | Swept cm3/stroke | Diaphragm D mm |', '|---|---|---|---|---|---|']
    md += [f"| {s['stage']} | {s['P_in_bar']:.1f} | {s['P_out_bar']:.1f} | {s['T_out_C']:.0f} | {s['swept_cm3']:.1f} | {s['diaphragm_D_mm']:.0f} |" for s in r['stages']]
    md += ['', 'Material: ' + r['material'] + '. Stage discharge about 200 C is above the usual diaphragm-head practice; a third stage (ratio 2.7, about 120 C) is the first option if the bench run shows head heating. Efficiencies, speed and cavity depth are assumptions until the first-article bench run (A-M-169).']
    open(os.path.join(ROOT, 'docs-authority/sizing/H2_COMPRESSOR.md'), 'w').write('\n'.join(md) + '\n')
def main():
    d = DR.load(); g = json.load(open(GP)); r = design(d, g); print(json.dumps(r, default=float))
    if '--write' in sys.argv: write(g, r)
if __name__ == '__main__': main()
